CustomField.formula:
IF(
  /*If Account is IMGA, stores Global_Account_Director__c */
 ISPICKVAL(IM_Hierarchy_Level__c, 'IM Group (IMGA)'), Global_Account_Director__c,
IF(
  /*If Account is Country Parent, stores IMGA Account's Global_Account_Director__c by traversing one level up the hierarchy*/
 ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'),  Parent.Global_Account_Director__c ,
IF(
  /*If Account is Sales site, stores IMGA Account's Global_Account_Director__c by traversing two levels up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(Parent.ParentId))), Parent.Parent.Global_Account_Director__c,Global_Account_Director__c)))
